import fs from 'node:fs';
import { HatchetClient } from '@hatchet-dev/typescript-sdk';

type ProcessOrderInput = {
  region: string;
};

const hatchet = HatchetClient.init();

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

const getRunId = () => {
  const runId = process.env.ZEALT_RUN_ID;
  if (!runId) {
    throw new Error('ZEALT_RUN_ID is required');
  }

  return runId;
};

const getLogPath = () => `/tmp/orders-${getRunId()}.log`;

const processOrder = hatchet.task<ProcessOrderInput, void>({
  name: 'processOrder',
  concurrency: {
    expression: 'input.region',
    maxRuns: 1,
  },
  fn: async (input) => {
    const logPath = getLogPath();
    const startTime = Date.now();
    fs.appendFileSync(logPath, `start ${input.region} ${startTime}\n`);
    await sleep(1500);
    const endTime = Date.now();
    fs.appendFileSync(logPath, `end ${input.region} ${endTime}\n`);
  },
});

export { hatchet, processOrder, getRunId, getLogPath };

import { hatchet, processOrder } from './hatchet.js';

const main = async () => {
  const worker = await hatchet.worker('process-order-worker', {
    workflows: [processOrder],
    slots: 10,
  });

  await worker.start();
};

main().catch((error) => {
  console.error('Worker failed to start:', error);
  process.exit(1);
});

import fs from 'node:fs';
import { processOrder, getLogPath, getRunId } from './hatchet.js';

const main = async () => {
  const runId = getRunId();
  const logPath = getLogPath();

  fs.writeFileSync(logPath, '');

  const usRegion = `US-${runId}`;
  const euRegion = `EU-${runId}`;

  await Promise.all([
    processOrder.run({ region: usRegion }),
    processOrder.run({ region: usRegion }),
    processOrder.run({ region: euRegion }),
    processOrder.run({ region: euRegion }),
  ]);
};

main().catch((error) => {
  console.error('Runner failed:', error);
  process.exit(1);
});
